32	// Node represents a single definition in a program or component.
33	// Nodes may be config, locals, resources, components, or outputs.
34	type Node interface {
35		model.Definition
36	
37		// Name returns the lexical name of the node.
38		Name() string
39	
40		// Type returns the type of the node.
41		Type() model.Type
42	
43		// VisitExpressions visits the expressions that make up the node's body.
44		VisitExpressions(pre, post model.ExpressionVisitor) hcl.Diagnostics
45	
46		markBinding()
47		markBound()
48		isBinding() bool
49		isBound() bool
50	
51		GetDependencies() []Node
52		setDependencies(nodes []Node)
53	
54		isNode()
55	}
56	
57	type node struct {
58		binding bool
59		bound   bool
60		deps    []Node
61	}
62	
63	func (r *node) markBinding() {
64		r.binding = true
65	}
66	
67	func (r *node) markBound() {
68		r.bound = true
69	}
70	
71	func (r *node) isBinding() bool {
72		return r.binding && !r.bound
73	}
74	
75	func (r *node) isBound() bool {
76		return r.bound
77	}
