199	// writeSourceFiles writes the source files of the program, including those files of used components into the
200	// provided file system starting from a root directory.
201	func (p *Program) writeSourceFiles(directory string, fs afero.Fs, seenPaths map[string]bool) error {
202		// create the directory if it doesn't already exist
203		err := fs.MkdirAll(directory, 0o755)
204		if err != nil {
205			return fmt.Errorf("could not create output directory: %w", err)
206		}
207	
208		for _, file := range p.files {
209			outputFile := path.Join(directory, file.Name)
210			err := afero.WriteFile(fs, outputFile, file.Bytes, 0o600)
211			if err != nil {
212				return fmt.Errorf("could not write output program: %w", err)
213			}
214		}
215	
216		for _, node := range p.Nodes {
217			switch node := node.(type) {
218			case *Component:
219				componentDirectory := path.Join(directory, node.source)
220				if _, seen := seenPaths[componentDirectory]; !seen {
221					seenPaths[componentDirectory] = true
222					err = node.Program.writeSourceFiles(componentDirectory, fs, seenPaths)
223					if err != nil {
224						return err
225					}
226				}
227			}
228		}
229	
230		return nil
231	}
232	
233	// WriteSource writes the source files of the program, including those files of used components into the
234	// provided file system.
235	func (p *Program) WriteSource(fs afero.Fs) error {
236		seenPaths := map[string]bool{}
237		return p.writeSourceFiles("/", fs, seenPaths)
238	}
239	
240	// collectComponentsRecursive is a helper function to find all used components in a program
241	// and recursively searches of nested components from sub programs.
242	func (p *Program) collectComponentsRecursive(components map[string]*Component) {
243		for _, node := range p.Nodes {
244			switch node := node.(type) {
245			case *Component:
246				if _, seen := components[node.DirPath()]; !seen {
247					components[node.DirPath()] = node
248					node.Program.collectComponentsRecursive(components)
249				}
250			}
251		}
252	}
