func hookDiagSummaries(diags hcl.Diagnostics) []string {
	var out []string
	for _, d := range diags {
		out = append(out, d.Summary)
	}
	return out
}

func TestScratchHookBasic(t *testing.T) {
	src := `
hook "myHook" {
  command = ["echo", args.urn, args.id, args.name, args.type]
}
`
	prog, diags, err := ParseAndBindProgram(t, src, "hook.pp")
	t.Logf("err=%v diags=%v", err, hookDiagSummaries(diags))
	if diags.HasErrors() {
		t.Fatalf("unexpected errors: %v", hookDiagSummaries(diags))
	}
	if prog == nil {
		t.Fatal("nil program")
	}
	hooks := prog.Hooks()
	if len(hooks) != 1 {
		t.Fatalf("expected 1 hook, got %d", len(hooks))
	}
	if hooks[0].Name() != "myHook" {
		t.Fatalf("unexpected hook name %q", hooks[0].Name())
	}
}

